#!/bin/sh
# Author: Navjyot Nishant
# Created: 2026-10-15
# Last updated: 2026-10-15
# Description: first start of the NAVAAN Postgres container: create the application role and database. Runs once, on an empty data folder.
#
# The superuser (postgres) is for the container's own maintenance. The app connects as navaan_app: it owns database navaan and what it creates in it, and
# cannot create roles or databases or read other databases' data. Both passwords are generated by the pg-init service and live in the pgadmin and pgapp volumes (the app container mounts only pgapp).
set -eu
APP_PW="$(cat /pgapp/pg_app_password)"
psql -v ON_ERROR_STOP=1 -U "$POSTGRES_USER" -d postgres <<SQL
CREATE ROLE navaan_app LOGIN PASSWORD '$APP_PW' NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION;
CREATE DATABASE navaan OWNER navaan_app;
REVOKE ALL ON DATABASE navaan FROM PUBLIC;
SQL
